const cfg = { wid: '{{BV:chatmaster.whatsapp_id}}', botao: "{{BV:textos.lista_botao}}", topo: "{{BV:textos.lista_topo}}", titulo_sim: "{{BV:mensagens.titulo_sim}}", titulo_nao: "{{BV:mensagens.titulo_nao}}", retentativas_min: {{BV:mensagens.retentativas_min}},
  textos: { confirmacao: "{{BV:textos.confirmacao}}", lembrete: "{{BV:textos.lembrete}}", pos: "{{BV:textos.pos}}" },
  teste: '{{BV:ambiente}}' === 'integracao' ? { testeId: '{{BV:graces.barbeiro_teste_id}}', escrita: {{BV:teste.contatos_escrita}} } : null }; // trava so no TESTE
const d = $('Decidir').item.json;
const base = { id: d.id, reserva: d.reserva };
if (d.acao === 'cancelar') return { json: { ...base, situacao: 'cancelada', motivo: d.motivo } };
if (d.acao === 'adiar') return { json: { ...base, situacao: 'pendente' } }; // libera a reserva; tenta na proxima varredura
const status = Number($input.item.json.statusCode || 0); // 0 = timeout/sem resposta: incerto, nunca reenvia
const r = bvMResultadoEnvio(status, d.tentativas, cfg, new Date());
const falha = r.situacao === 'enviada' ? {} : { falha_motivo: status === 0 ? 'mensagem|envio_incerto' : 'mensagem|envio_falhou', code: status === 0 ? 'SEM_RESPOSTA' : `HTTP_${status}`, status };
return { json: { ...base, situacao: r.situacao, motivo: r.motivo, tentativas: r.tentativas, proxima: r.proxima_tentativa_em, ...(r.situacao === 'enviada' ? { tipo_msg: d.tipo_msg, texto: d.texto } : {}), ...falha } };

const hoje = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(new Date());
const dia = (n) => new Date(Date.parse(hoje + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
// inicio = ontem: o Ler estado le desde ontem; sem isso o pos_atendimento de ontem viraria orfa
return [{ json: { hoje, inicio: dia(-1), fim: dia({{BV:mensagens.reconciliacao_dias}}) } }];

