// TESTE (integracao): so a agenda do barbeiro de teste; fora do TESTE: todos menos o de teste (nunca vai a cliente)
const r = $input.first().json;
if (Number(r.statusCode) !== 200 || !Array.isArray(r.body)) return [{ json: { ok: false, status: Number(r.statusCode || 0) } }];
const teste = '{{BV:graces.barbeiro_teste_id}}', soTeste = '{{BV:ambiente}}' === 'integracao';
const agenda = bvMAgendaDe(r.body.filter((p) => p && (p.idProfissional === teste) === soTeste));
return [{ json: { ok: true, agenda } }];

