const cfg = { reconciliacao_dias: {{BV:mensagens.reconciliacao_dias}}, confirmacao_hora: "{{BV:mensagens.confirmacao_hora}}", lembrete_antes_min: {{BV:mensagens.lembrete_antes_min}}, pos_depois_min: {{BV:mensagens.pos_depois_min}} };
const agenda = $('Achatar').first().json.agenda;
const e = $input.first().json;
const r = bvMReconciliar(agenda, e.linhas || [], e.contatos || [], new Date(), cfg);
// 'reagendada' e substituida pelo upsert do Aplicar (mesmo idAgenda e tipo): cancelar a antiga aqui disputaria a mesma linha
const cancelar = r.cancelar.filter((c) => c.motivo !== 'reagendada').map((c) => ({ id: c.id, motivo: c.motivo }));
const criar = r.criar.map((c) => ({ contato_id: c.contato_id, tipo: c.tipo, previsto_para: c.previsto_para, idAgenda: c.idAgenda, idProfissional: c.idProfissional, inicio: c.horaInicio,
  dados: { servico: c.nomeServico, barbeiro: c.profissional, fim: c.horaFim } }));
return [{ json: { cancelar, criar, sem_contato: [...new Set(r.sem_contato)], recorrente: r.recorrente } }];
